context-drift-test.cc<pre><code>/*
Authors: Rahul R, Dr. Subbulakshmi T, Arun Santhosh R A
Github id: Rahul2671
VIT Chennai, India
*/

/*The below code does the following:
* Simulates IoT node behavior by generating deterministic context data (time, congestion, proximity).
* Establishes baseline profiles for nodes to compare current behavior against normal patterns.
* Injects progressive drift ranging from perfectly normal (Node 1) to severe anomalies (Node 3).
* Triggers a "Rare Attack" mid-simulation to test detection of extreme data outliers on Node 4.
* Periodically revalidates trust using weighted attributes and a threshold to identify compromised nodes.
*/

#include &lt;cstdint&gt;
#include "ns3/core-module.h"
#include "ns3/zero-trust-iot-module.h"

#include &lt;vector&gt;

using namespace ns3;

ContextAttributeStore *g_store;
PeriodicRevalidator *g_validator;

std::vector&lt;uint32_t&gt; nodes = {1,2,3,4};

bool rareAttack = false;

/* --------------------------------
 * Deterministic Context Generator
 * -------------------------------- */
void UpdateContext ()
{
  for (auto nodeId : nodes)
  {
    double timeCtx;
    double congestion;
    uint32_t proximity;

    // ==========================
    // Node 4 → Rare extreme case
    // ==========================
    if (rareAttack &amp;&amp; nodeId == 4)
    {
      timeCtx = 23;
      congestion = 0.99;
      proximity = 15;

      ZtLogger::Log("NORMAL-TEST", "Extreme drift (Node 4)");
    }

    // ==========================
    // Node 3 → Severe drift
    // ==========================
    else if (nodeId == 3)
    {
      timeCtx = 18;
      congestion = 0.75;
      proximity = 8;

      ZtLogger::Log("NORMAL-TEST", "Severe drift (Node 3)");
    }

    // ==========================
    // Node 2 → Mild drift
    // ==========================
    else if (nodeId == 2)
    {
      timeCtx = 12;
      congestion = 0.30;
      proximity = 3;

      ZtLogger::Log("NORMAL-TEST", "Mild drift (Node 2)");
    }

    // ==========================
    // Node 1 → Perfectly normal
    // ==========================
    else
    {
      timeCtx = 10;
      congestion = 0.10;
      proximity = 2;

      ZtLogger::Log("NORMAL-TEST", "Normal behavior (Node 1)");
    }

    g_store-&gt;UpdateCurrentContext(nodeId, timeCtx, congestion, proximity);
  }

  Simulator::Schedule(Seconds(1.0), &amp;UpdateContext);
}

/* -------------------------------- */
void ValidateLoop ()
{
  g_validator-&gt;Revalidate();
  Simulator::Schedule(Seconds(1.0), &amp;ValidateLoop);
}

/* -------------------------------- */
void TriggerRareAttack ()
{
  rareAttack = true;
  ZtLogger::Log("NORMAL-TEST", "&gt;&gt;&gt; RARE ATTACK ACTIVATED &lt;&lt;&lt;");
}

/* -------------------------------- */
int main(int argc, char *argv[])
{
  Time::SetResolution(Time::NS);

  ZtPolicyEngine policy;
  ContextAttributeStore store;

  for (auto n : nodes)
  {
    policy.AddAuthorized(n, "generic-device");
    policy.Authorize(n, "generic-device");

    store.StoreBaseline(n, 10, 0.10, 2);
  }

  PeriodicRevalidator validator(&amp;policy, &amp;store);

  validator.SetParameters(
      0.35, // time weight
      0.35, // congestion weight
      0.30, // proximity weight
      0.05, // lambda (UPDATED from 0.50 → 0.05)
      0.40 // trust threshold
  );

  for (auto n : nodes)
    validator.AddActiveNode(n);

  g_store = &amp;store;
  g_validator = &amp;validator;

  Simulator::Schedule(Seconds(1.0), &amp;UpdateContext);
  Simulator::Schedule(Seconds(2.0), &amp;ValidateLoop);

  Simulator::Schedule(Seconds(8.0), &amp;TriggerRareAttack);

  Simulator::Stop(Seconds(18.0));
  Simulator::Run();
  Simulator::Destroy();

  return 0;
}
</code></pre>

micro-segmentation-test.cc<pre><code>/*
Authors:Rahul S,Dr.Subbulakshmi T,Arun Santhosh R A
Github ID:Rahul-252506
VIT CHENNAI,INDIA
*/

/*The below code does the following:

* Implements role-based micro-segmentation for a camera, analytics server, and maintenance device.
* Enforces time-bound policies that only allow maintenance updates during specific early morning hours.
* Applies rate-limiting constraints by blocking traffic once the maximum number of transfers is exceeded.
* Simulates dynamic enforcement by evaluating real-time access requests against defined security rules.
* Adheres to Zero Trust principles by defaulting to "DENY" for unauthorized actions like rebooting.

*/
#include "ns3/core-module.h"
#include "ns3/network-module.h"
#include "ns3/zero-trust-iot-module.h"

using namespace ns3;

int main(int argc, char *argv[])
{
  NodeContainer nodes;
  nodes.Create(3);

  Ptr&lt;Node&gt; camera = nodes.Get(0);
  Ptr&lt;Node&gt; analytics = nodes.Get(1);
  Ptr&lt;Node&gt; maintenance = nodes.Get(2);

  IdentityRegistry&amp; registry = IdentityRegistry::GetInstance();

  registry.RegisterNode(camera, "Camera");
  registry.RegisterNode(analytics, "AnalyticsServer");
  registry.RegisterNode(maintenance, "MaintenanceDevice");

  Ptr&lt;ZtPolicyEngine&gt; engine = CreateObject&lt;ZtPolicyEngine&gt;();

  // Camera streaming rule
  ZtPolicyEngine::RolePolicyRule streamRule;
  streamRule.srcRole = "Camera";
  streamRule.dstRole = "AnalyticsServer";
  streamRule.action = "STREAM";
  streamRule.startHour = 0;
  streamRule.endHour = 24;
  streamRule.windowSeconds = 30;
  streamRule.maxTransfers = 5;
  streamRule.effect = ZtPolicyEngine::ALLOW;

  engine-&gt;AddRolePolicyRule(streamRule);

  // Maintenance update rule (restricted time window)
  ZtPolicyEngine::RolePolicyRule updateRule;
  updateRule.srcRole = "MaintenanceDevice";
  updateRule.dstRole = "AnalyticsServer";
  updateRule.action = "UPDATE";
  updateRule.startHour = 2; // 2 AM
  updateRule.endHour = 4; // 4 AM
  updateRule.windowSeconds = 60;
  updateRule.maxTransfers = 2;
  updateRule.effect = ZtPolicyEngine::ALLOW;

  engine-&gt;AddRolePolicyRule(updateRule);

  std::cout &lt;&lt; "\n--- Dynamic Trust Enforcement Demo ---\n";

  // Valid streaming
  bool d1 = engine-&gt;EvaluateMicroSegmentation(camera, analytics, "STREAM");
  std::cout &lt;&lt; "Camera STREAM → " &lt;&lt; (d1 ? "ALLOW" : "DENY") &lt;&lt; "\n";

  // Exceed stream threshold
  for (int i = 0; i &lt; 6; ++i)
      engine-&gt;EvaluateMicroSegmentation(camera, analytics, "STREAM");

  bool d2 = engine-&gt;EvaluateMicroSegmentation(camera, analytics, "STREAM");
  std::cout &lt;&lt; "Camera Excess STREAM → " &lt;&lt; (d2 ? "ALLOW" : "DENY") &lt;&lt; "\n";

  // Maintenance attempt (likely denied unless current hour is 2–4)
  bool d3 = engine-&gt;EvaluateMicroSegmentation(maintenance, analytics, "UPDATE");
  std::cout &lt;&lt; "Maintenance UPDATE → " &lt;&lt; (d3 ? "ALLOW" : "DENY") &lt;&lt; "\n";

  // Unknown action
  bool d4 = engine-&gt;EvaluateMicroSegmentation(camera, analytics, "REBOOT");
  std::cout &lt;&lt; "Camera REBOOT → " &lt;&lt; (d4 ? "ALLOW" : "DENY") &lt;&lt; "\n";

  return 0;
}
</code></pre>

trust-scorer-test.cc<pre><code>//zt-trust-test.cc

/*
Authors:Muthu Venkatesh M,Dr Subbulakshmi T,Arun Santhosh R A
Github id:muthuvenkatesh-24
VIT-Chennai
*/


/*

The test does the following:

• Checks whether the function maintains a trust score (0–100) per session (src → dst)
• Learns a baseline packet rate using a sliding time window
• Detects trust violations when deviation exceeds 1.5× baseline
• Checks with regard to different types of attacks(Normal Behaviour , Violation Burst)
• Applies exponential penalty for consecutive violations
• Rewards normal behaviour with gradual recovery
• Blocks the session and rejects the packets if trust score is below the threshold

*/


#include "ns3/core-module.h"
#include "ns3/network-module.h"
#include "ns3/zero-trust-iot-module.h"

using namespace ns3;

static void SendNormal(uint32_t src, uint32_t dst)
{
    std::cout &lt;&lt; "Normal packet" &lt;&lt; std::endl;
    ZtDynamicTrustScorer::OnPacketReceived(src, dst, 6, 8080);
}

static void SendBurst(uint32_t src, uint32_t dst)
{
    std::cout &lt;&lt; "Violation burst" &lt;&lt; std::endl;

    for (int i = 0; i &lt; 5; ++i)
    {
        Simulator::Schedule(MilliSeconds(i * 50),
            &amp;ZtDynamicTrustScorer::OnPacketReceived,
            src, dst, 6, 8080);
    }
}

int main()
{
    uint32_t src = 0;
    uint32_t dst = 1;

    Simulator::Schedule(Seconds(1.0), &amp;SendNormal, src, dst);
    Simulator::Schedule(Seconds(2.0), &amp;SendNormal, src, dst);
    Simulator::Schedule(Seconds(3.0), &amp;SendBurst,  src, dst);
    Simulator::Schedule(Seconds(7.0), &amp;SendNormal, src, dst);
    Simulator::Schedule(Seconds(8.0), &amp;SendBurst,  src, dst);

    Simulator::Stop(Seconds(15.0));
    Simulator::Run();
    Simulator::Destroy();
}
</code></pre>

zt-certificate.h<pre><code>#ifndef ZT_CERTIFICATE_H
#define ZT_CERTIFICATE_H

#include &lt;string&gt;
#include &lt;ctime&gt;
#include &lt;unordered_set&gt;
#include &lt;cryptopp/rsa.h&gt;
#include &lt;cryptopp/base64.h&gt;

/**
 * \class CertificateAuthority
 * \brief Simulates a Certificate Authority (CA) that issues and signs identity certificates.
 *
 * The CA generates a public-private RSA key pair and uses it to sign certificates
 * for nodes, which include identity, role, and expiry information.
 */
class CertificateAuthority {
public:
  /**
   * \brief Constructor that initializes and generates RSA key pair.
   */
  CertificateAuthority();

  /**
   * \brief Signs an identity certificate with node ID, role, and expiry.
   * \param nodeId The unique identifier of the node.
   * \param role The assigned role of the node (e.g., "sensor", "gateway").
   * \param expiry Expiry timestamp for the certificate.
   * \return A signed certificate string in plain format with a base64-encoded signature.
   */
  std::string SignIdentity(uint32_t nodeId, const std::string&amp; role, time_t expiry);

  /**
   * \brief Retrieves the public RSA key of the CA.
   * \return The public key corresponding to the CA's private key.
   */
  CryptoPP::RSA::PublicKey GetPublicKey() const;

private:
  CryptoPP::RSA::PrivateKey privateKey; ///&lt; RSA private key used for signing certificates.
  CryptoPP::RSA::PublicKey publicKey;   ///&lt; RSA public key distributed for verification.
};

/**
 * \class ZtPolicyEngineWithCert
 * \brief Simulates a Zero Trust policy engine that enforces access control using certificates.
 *
 * This engine validates node certificates, verifies digital signatures, checks role and expiry,
 * and maintains a list of revoked node IDs.
 */
class ZtPolicyEngineWithCert {
public:
  /**
   * \brief Sets the CA's public key used for certificate verification.
   * \param pub The public RSA key of the trusted Certificate Authority.
   */
  void SetCaPublicKey(CryptoPP::RSA::PublicKey pub);

  /**
   * \brief Revokes a node by its ID, preventing it from being authorized.
   * \param nodeId The node ID to be added to the revocation list.
   */
  void Revoke(uint32_t nodeId);

  /**
   * \brief Authorizes a node based on its certificate.
   * \param nodeId The node's claimed ID.
   * \param role The role the node claims to perform.
   * \param certStr The certificate string presented by the node.
   * \return True if the certificate is valid, not expired, matches the node, and not revoked.
   */
  bool Authorize(uint32_t nodeId, const std::string&amp; role, const std::string&amp; certStr);

private:
  CryptoPP::RSA::PublicKey caPublicKey; ///&lt; Trusted public key used for signature verification.
  std::unordered_set&lt;uint32_t&gt; revoke;  ///&lt; Set of node IDs that are explicitly revoked.
};

#endif // ZT_CERTIFICATE_H
</code></pre>

zt-certificate.cc<pre><code>#include "zt-certificate.h"
#include &lt;cryptopp/osrng.h&gt;
#include &lt;cryptopp/pssr.h&gt;
#include &lt;cryptopp/sha.h&gt;
#include &lt;cryptopp/filters.h&gt;
#include &lt;cryptopp/files.h&gt;
#include &lt;sstream&gt;
#include &lt;ns3/core-module.h&gt;

using namespace CryptoPP;

/**
 * \class CertificateAuthority
 * \brief Issues and signs certificates for Zero Trust identity validation.
 */
CertificateAuthority::CertificateAuthority() {
  AutoSeededRandomPool prng;
  privateKey.GenerateRandomWithKeySize(prng, 1024);
  publicKey = privateKey;
}

/**
 * \brief Signs a certificate with node ID, role, and expiry.
 * \param nodeId ID of the node requesting certificate
 * \param role Role assigned to the node (e.g., sensor, gateway)
 * \param expiry Expiry timestamp of the certificate
 * \return Signed certificate string with base64-encoded signature
 */
std::string CertificateAuthority::SignIdentity(uint32_t nodeId, const std::string&amp; role, time_t expiry) {
  AutoSeededRandomPool prng;

  std::ostringstream cert;
  cert &lt;&lt; "ID:" &lt;&lt; nodeId &lt;&lt; "|ROLE:" &lt;&lt; role &lt;&lt; "|EXP:" &lt;&lt; expiry;

  RSASS&lt;PSSR, SHA1&gt;::Signer signer(privateKey);
  std::string signature;
  StringSource(cert.str(), true,
    new SignerFilter(prng, signer,
      new StringSink(signature)));

  std::string encodedSig;
  StringSource(signature, true,
    new Base64Encoder(new StringSink(encodedSig), false));

  return cert.str() + "|SIG:" + encodedSig;
}

/**
 * \brief Returns the public key of the Certificate Authority.
 * \return RSA public key
 */
RSA::PublicKey CertificateAuthority::GetPublicKey() const {
  return publicKey;
}

/**
 * \brief Sets the CA public key for the policy engine.
 * \param pub RSA public key of the certificate authority
 */
void ZtPolicyEngineWithCert::SetCaPublicKey(RSA::PublicKey pub) {
  caPublicKey = pub;
}

/**
 * \brief Revokes access for a specific node.
 * \param nodeId ID of the node to be revoked
 */
void ZtPolicyEngineWithCert::Revoke(uint32_t nodeId) {
  revoke.insert(nodeId);
}

/**
 * \brief Verifies and authorizes a node based on its certificate.
 * \param nodeId ID of the node attempting access
 * \param role Role of the node
 * \param certStr Certificate string to validate
 * \return True if the certificate is valid and authorization succeeds
 */
bool ZtPolicyEngineWithCert::Authorize(uint32_t nodeId, const std::string&amp; role, const std::string&amp; certStr) {
  using namespace ns3;

  if (revoke.find(nodeId) != revoke.end()) {
    NS_LOG_UNCOND("ZT-CERT: Node " &lt;&lt; nodeId &lt;&lt; " is revoked");
    return false;
  }

  std::string content, sig;
  size_t sigPos = certStr.find("|SIG:");
  if (sigPos == std::string::npos) return false;
  content = certStr.substr(0, sigPos);
  sig = certStr.substr(sigPos + 5);

  std::string decodedSig;
  StringSource(sig, true, new Base64Decoder(new StringSink(decodedSig)));

  RSASS&lt;PSSR, SHA1&gt;::Verifier verifier(caPublicKey);
  bool valid = false;
  StringSource(decodedSig + content, true,
    new SignatureVerificationFilter(verifier,
      new ArraySink((byte*)&amp;valid, sizeof(valid)),
      SignatureVerificationFilter::PUT_RESULT | SignatureVerificationFilter::SIGNATURE_AT_BEGIN));

  if (!valid) {
    NS_LOG_UNCOND("ZT-CERT: Signature invalid");
    return false;
  }

  std::istringstream ss(content);
  std::string token;
  uint32_t idParsed = 0;
  std::string roleParsed;
  time_t expiry = 0;

  while (std::getline(ss, token, '|')) {
    if (token.find("ID:") == 0)
      idParsed = std::stoul(token.substr(3));
    else if (token.find("ROLE:") == 0)
      roleParsed = token.substr(5);
    else if (token.find("EXP:") == 0)
      expiry = std::stol(token.substr(4));
  }

  if (idParsed != nodeId || roleParsed != role) {
    NS_LOG_UNCOND("ZT-CERT: Identity mismatch");
    return false;
  }

  time_t now = std::time(nullptr);
  if (now &gt; expiry) {
    NS_LOG_UNCOND("ZT-CERT: Certificate expired");
    return false;
  }

  return true;
}
</code></pre>

zt-context-drift-validator.h<pre><code>// zt-context-drift-validator.h

/*
Authors: Rahul R, Dr. Subbulakshmi T, Arun Santhosh R A
Github id: Rahul2671
VIT Chennai, India
*/


/* 
The below code does the following:
Even after a node is authenticated and authorized successfully,
its access should NOT remain permanent. The node's operational
context is continuously monitored. If the context drifts too much
from the baseline captured during handshake, trust is gradually
reduced and access is revoked.
*/


#ifndef ZT_CONTEXT_DRIFT_VALIDATOR_H
#define ZT_CONTEXT_DRIFT_VALIDATOR_H

#include &lt;map&gt;
#include &lt;set&gt;
#include &lt;cstdint&gt;

#include "zt-policy-engine.h"   // MUST be here, before namespace

namespace ns3 {

/**
 * ============================================================
 * // Zero Trust Context Drift Validator
 * ============================================================
 */

/**
 * ============================================================
 * CLASS: ContextAttributeStore
 * ============================================================
 */

 // Stores baseline and runtime context of nodes

class ContextAttributeStore
{
public:

  void StoreBaseline(uint32_t nodeId,
                     double timeOfDay,
                     double congestion,
                     uint32_t proximity);

  void UpdateCurrentContext(uint32_t nodeId,
                            double timeOfDay,
                            double congestion,
                            uint32_t proximity);

  double CalculateDrift(uint32_t nodeId,
                      double wt,
                      double wc,
                      double wp) const;

  void UpdateTrust(uint32_t nodeId,
                   double drift,
                   double lambda);

  double GetTrust(uint32_t nodeId) const;

private:

  std::map&lt;uint32_t, double&gt; baselineTime;
  std::map&lt;uint32_t, double&gt; baselineCongestion;
  std::map&lt;uint32_t, uint32_t&gt; baselineProximity;

  std::map&lt;uint32_t, double&gt; currentTime;
  std::map&lt;uint32_t, double&gt; currentCongestion;
  std::map&lt;uint32_t, uint32_t&gt; currentProximity;

  std::map&lt;uint32_t, double&gt; trustScore;
};


/**
 * ============================================================
 * CLASS: PeriodicRevalidator
 * ============================================================
 */

 // Periodically evaluates node trust and revokes low-trust compromised nodes

class PeriodicRevalidator
{
public:

  PeriodicRevalidator(ZtPolicyEngine* policy,
                      ContextAttributeStore* store);

  void SetParameters(double wt,
                     double wc,
                     double wp,
                     double lambda,
                     double threshold);

  void AddActiveNode(uint32_t nodeId);

  void Revalidate();

private:

  ZtPolicyEngine* m_policy;
  ContextAttributeStore* m_store;
  // Non-owning pointers (lifetime managed externally)

  std::set&lt;uint32_t&gt; activeNodes;

  double WT = 0.0;
  double WC = 0.0;
  double WP = 0.0;
  double LAMBDA = 0.0;
  double TRUST_THRESHOLD = 0.0;
};

} // namespace ns3

#endif // ZT_CONTEXT_DRIFT_VALIDATOR_H
</code></pre>

zt-context-drift-validator.cc<pre><code>// zt-context-drift-validator.cc

/*
Authors: Rahul R, Dr. Subbulakshmi T, Arun Santhosh R A
Github id: Rahul2671
VIT Chennai, India
*/


/* 
The below code does the following:
Even after a node is authenticated and authorized successfully,
its access should NOT remain permanent. The node's operational
context is continuously monitored. If the context drifts too much
from the baseline captured during handshake, trust is gradually
reduced and access is revoked.
*/


#include "zt-context-drift-validator.h"
#include "zt-policy-engine.h"

#include &lt;cmath&gt;
#include &lt;iostream&gt;

namespace ns3 {

/**
 * ============================================================
 * ContextAttributeStore IMPLEMENTATION
 * ============================================================
 */

 // Baseline operating context captured during node onboarding

void
ContextAttributeStore::StoreBaseline(uint32_t nodeId,
                                     double timeOfDay,
                                     double congestion,
                                     uint32_t proximity)
// Baseline captured when node is first authorized

{
  baselineTime[nodeId] = timeOfDay;
  baselineCongestion[nodeId] = congestion;
  baselineProximity[nodeId] = proximity;

  currentTime[nodeId] = timeOfDay;
  currentCongestion[nodeId] = congestion;
  currentProximity[nodeId] = proximity;

  trustScore[nodeId] = 1.0;
}

void
ContextAttributeStore::UpdateCurrentContext(uint32_t nodeId,
                                            double timeOfDay,
                                            double congestion,
                                            uint32_t proximity)
{
  currentTime[nodeId] = timeOfDay;
  currentCongestion[nodeId] = congestion;
  currentProximity[nodeId] = proximity;
}

double
ContextAttributeStore::CalculateDrift(uint32_t nodeId,
                                      double wt,
                                      double wc,
                                      double wp)

{
  // Time deviation
  double dt = std::abs(currentTime[nodeId] - baselineTime[nodeId]);
  // Network deviation
  double dc = std::abs(currentCongestion[nodeId] - baselineCongestion[nodeId]);
  // Location deviation
  double dp = std::abs((double)currentProximity[nodeId] -
                        (double)baselineProximity[nodeId]);

  return wt * dt + wc * dc + wp * dp;
}

void
ContextAttributeStore::UpdateTrust(uint32_t nodeId,
                                   double drift,
                                   double lambda)
{
  trustScore[nodeId] *= std::exp(-lambda * drift);

  if (trustScore[nodeId] &lt; 0.0)
    trustScore[nodeId] = 0.0;
}

double
ContextAttributeStore::GetTrust(uint32_t nodeId) const
{
  auto it = trustScore.find(nodeId);
  if (it != trustScore.end())
    return it-&gt;second;

  return 0.0;
}

/**
 * ============================================================
 * PeriodicRevalidator IMPLEMENTATION
 * ============================================================
 */ 

PeriodicRevalidator::PeriodicRevalidator(ZtPolicyEngine* policy,
                                         ContextAttributeStore* store)
{
  m_policy = policy;
  m_store = store;
}

void
PeriodicRevalidator::SetParameters(double wt,
                                   double wc,
                                   double wp,
                                   double lambda,
                                   double threshold)
{
  WT = wt;
  WC = wc;
  WP = wp;
  LAMBDA = lambda;
  TRUST_THRESHOLD = threshold;
}

void
PeriodicRevalidator::AddActiveNode(uint32_t nodeId)
{
  activeNodes.insert(nodeId);
}

void
PeriodicRevalidator::Revalidate()
{
  for (auto nodeId : activeNodes)
  {
    double drift = m_store-&gt;CalculateDrift(nodeId, WT, WC, WP);

    m_store-&gt;UpdateTrust(nodeId, drift, LAMBDA);

    double trust = m_store-&gt;GetTrust(nodeId);

    std::cout &lt;&lt; "[ZeroTrust] Node"
 &lt;&lt; nodeId
              &lt;&lt; " Drift=" &lt;&lt; drift
              &lt;&lt; " Trust=" &lt;&lt; trust &lt;&lt; std::endl;

    if (trust &lt; TRUST_THRESHOLD)

      m_policy-&gt;Revoke(nodeId);

      std::cout &lt;&lt; "[ZeroTrust] Node "
 &lt;&lt; nodeId
                &lt;&lt; " revoked due to low trust" &lt;&lt; std::endl;
    }
  }
}

} 
</code></pre>

zt-dynamic-trust-scorer.h<pre><code>//zt-dynamic-trust-scorer.h

/*
Authors:Muthu Venkatesh M,Dr Subbulakshmi T,Arun Santhosh R A
Github id:muthuvenkatesh-24
VIT-Chennai
*/


/*
The function does the following:
• Maintains a trust score (0–100) per session (src → dst)
• Learns a baseline packet rate using a sliding time window
• Detects trust violations when deviation exceeds 1.5× baseline
• Applies exponential penalty for consecutive violations
• Rewards normal behaviour with gradual recovery
*/


#ifndef ZT_DYNAMIC_TRUST_SCORER_H
#define ZT_DYNAMIC_TRUST_SCORER_H

#include &lt;map&gt;
#include &lt;deque&gt;
#include &lt;cstdint&gt;

#include "zt-policy-engine.h"
#include "zt-logger.h"

namespace ns3 {

class ZtDynamicTrustScorer
{
public:

    /* ======== Core DTS ======== */

    static void OnPacketReceived(uint32_t srcNode,
                                 uint32_t dstNode,
                                 uint16_t protocol,
                                 uint16_t dstPort);

    static bool IsSessionAllowed(uint32_t srcNode,
                                 uint32_t dstNode);

    /* ======== Traffic Generator (Merged Secure App) ======== */

    static void StartTraffic(uint32_t srcNode,
                             uint32_t dstNode);

private:

    static void SendTraffic(uint32_t srcNode,
                            uint32_t dstNode);

    struct PacketObservation
    {
        double timestamp;
        uint16_t protocol;
        uint16_t dstPort;
    };

    struct TrustState
    {
        double trustScore;
        std::deque&lt;PacketObservation&gt; window;
        bool baselineInitialized;
        double baselinePacketRate;
        bool blocked;
        int consecutiveViolations;

        TrustState()
            : trustScore(100.0),
              baselineInitialized(false),
              baselinePacketRate(0.0),
              blocked(false),
              consecutiveViolations(0)
        {
        }
    };

    static std::map&lt;uint64_t, TrustState&gt; m_trustTable;
    static std::map&lt;uint64_t, uint32_t&gt;   m_packetCounters;

    static uint64_t MakeSessionKey(uint32_t srcNode, uint32_t dstNode);
    static void UpdateWindow(TrustState &amp;state,
                             uint16_t protocol,
                             uint16_t dstPort);
    static double ComputeDeviation(const TrustState &amp;state);
};

} // namespace ns3

#endif
