  void RegisterNode(Ptr&lt;Node&gt; node, const std::string&amp; role);

  std::string GetIdentityHash(Ptr&lt;Node&gt; node) const;
  std::string GetRole(Ptr&lt;Node&gt; node) const;

private:
  IdentityRegistry() {}

  // nodeId -&gt; (role, identityHash)
