zt-policy-engine.cc<pre><code>// === zt-policy-engine.cc ===
#include "zt-policy-engine.h"
#include "zt-identity-registry.h"
#include "zt-hash-utils.h"

#include &lt;ns3/log.h&gt;
#include &lt;sstream&gt;
#include &lt;ctime&gt;
#include &lt;algorithm&gt;
#include &lt;iostream&gt;

// Crypto++
#include &lt;cryptopp/base64.h&gt;
#include &lt;cryptopp/filters.h&gt;
#include &lt;cryptopp/pssr.h&gt;
#include &lt;cryptopp/sha.h&gt;

namespace ns3 {

NS_LOG_COMPONENT_DEFINE("ZtPolicyEngine");
NS_OBJECT_ENSURE_REGISTERED(ZtPolicyEngine);

// ===================== TypeId =====================
TypeId ZtPolicyEngine::GetTypeId() {
  static TypeId tid = TypeId("ZtPolicyEngine")
    .SetParent&lt;Object&gt;()
    .SetGroupName("ZeroTrust")
    .AddConstructor&lt;ZtPolicyEngine&gt;();
  return tid;
}

// ===================== Constructor =====================
ZtPolicyEngine::ZtPolicyEngine()
  : m_policyVersion(0)
{
}

// ===================== Destructor (ADDED FIX) =====================
ZtPolicyEngine::~ZtPolicyEngine()
{
}

// ===================== BASIC AUTH =====================
void ZtPolicyEngine::AddAuthorized(uint32_t nodeId, const std::string&amp; role) {
  authTable[nodeId] = role;
}

bool ZtPolicyEngine::Authorize(uint32_t nodeId, const std::string&amp; role) {
  return authTable.find(nodeId) != authTable.end() &amp;&amp;
         authTable[nodeId] == role;
}

// ===================== CERTIFICATE =====================
void ZtPolicyEngine::SetCaPublicKey(RSA::PublicKey pub) {
  caPublicKey = pub;
}

void ZtPolicyEngine::Revoke(uint32_t nodeId) {
  revoke.insert(nodeId);
}

bool ZtPolicyEngine::AuthorizeWithCert(uint32_t nodeId,
                                       const std::string&amp; role,
                                       const std::string&amp; certStr) {
  if (revoke.find(nodeId) != revoke.end()) {
    NS_LOG_UNCOND("ZT-CERT: Node " &lt;&lt; nodeId &lt;&lt; " is revoked");
    return false;
  }

  std::string content, sig;
  size_t sigPos = certStr.find("|SIG:");
  if (sigPos == std::string::npos) return false;

  content = certStr.substr(0, sigPos);
  sig = certStr.substr(sigPos + 5);

  std::string decodedSig;
  CryptoPP::StringSource(sig, true,
    new CryptoPP::Base64Decoder(
      new CryptoPP::StringSink(decodedSig)));

  CryptoPP::RSASS&lt;CryptoPP::PSSR, CryptoPP::SHA1&gt;::Verifier verifier(caPublicKey);

  bool valid = false;
  CryptoPP::StringSource(decodedSig + content, true,
    new CryptoPP::SignatureVerificationFilter(
      verifier,
      new CryptoPP::ArraySink((byte*)&amp;valid, sizeof(valid)),
      CryptoPP::SignatureVerificationFilter::PUT_RESULT |
      CryptoPP::SignatureVerificationFilter::SIGNATURE_AT_BEGIN));

  if (!valid) {
    NS_LOG_UNCOND("ZT-CERT: Signature invalid");
    return false;
  }

  std::istringstream ss(content);
  std::string token;
  uint32_t idParsed = 0;
  std::string roleParsed;
  time_t expiry = 0;

  while (std::getline(ss, token, '|')) {
    if (token.find("ID:") == 0)
      idParsed = std::stoul(token.substr(3));
    else if (token.find("ROLE:") == 0)
      roleParsed = token.substr(5);
    else if (token.find("EXP:") == 0)
      expiry = std::stol(token.substr(4));
  }

  if (idParsed != nodeId || roleParsed != role) {
    NS_LOG_UNCOND("ZT-CERT: Identity mismatch");
    return false;
  }

  if (std::time(nullptr) &gt; expiry) {
    NS_LOG_UNCOND("ZT-CERT: Certificate expired");
    return false;
  }

  return true;
}

// ===================== MICRO-SEGMENTATION =====================

// Add rule
void ZtPolicyEngine::AddRolePolicyRule(const RolePolicyRule&amp; rule) {
  m_rules.push_back(rule);
  m_policyVersion++;

  std::cout &lt;&lt; "[POLICY] Rule Added. Version: "
            &lt;&lt; m_policyVersion &lt;&lt; "\n";
}

// Time check
bool ZtPolicyEngine::IsWithinTime(uint32_t startHour,
                                 uint32_t endHour) {
  std::time_t now = std::time(nullptr);
  std::tm* local = std::localtime(&amp;now);
  uint32_t hour = local-&gt;tm_hour;

  return (hour &gt;= startHour &amp;&amp; hour &lt; endHour);
}

// Behavior tracking
uint32_t ZtPolicyEngine::GetBehaviorState(uint32_t nodeId,
                                          uint32_t windowSeconds) {
  uint64_t now = std::time(nullptr);
  auto&amp; history = m_transferHistory[nodeId];

  history.erase(
    std::remove_if(history.begin(), history.end(),
      [&amp;](uint64_t t) { return now - t &gt; windowSeconds; }),
    history.end());

  return history.size();
}

// Core evaluation
bool ZtPolicyEngine::EvaluateMicroSegmentation(
    Ptr&lt;Node&gt; srcNode,
    Ptr&lt;Node&gt; dstNode,
    const std::string&amp; action) {

  if (!srcNode || !dstNode) {
    std::cout &lt;&lt; "[MICRO-SEG] Invalid Node Pointer\n";
    return false;
  }

  IdentityRegistry&amp; registry =
      IdentityRegistry::GetInstance();

  std::string Hs = registry.GetIdentityHash(srcNode);
  std::string Hd = registry.GetIdentityHash(dstNode);

  std::string srcRole = registry.GetRole(srcNode);
  std::string dstRole = registry.GetRole(dstNode);

  uint32_t nodeId = srcNode-&gt;GetId();

  std::time_t now = std::time(nullptr);
  std::tm* local = std::localtime(&amp;now);
  uint32_t currentHour = local-&gt;tm_hour;

  for (const auto&amp; rule : m_rules) {
    if (rule.srcRole == srcRole &amp;&amp;
        rule.dstRole == dstRole &amp;&amp;
        (rule.action == action || rule.action == "*")) {

      if (!IsWithinTime(rule.startHour, rule.endHour))
        continue;

      uint32_t transferCount =
          GetBehaviorState(nodeId, rule.windowSeconds);

      uint32_t behaviorState =
          (transferCount &lt;= rule.maxTransfers) ? 0 : 1;

      std::string S =
          Hs + Hd +
          action +
          std::to_string(currentHour) +
          rule.srcRole +
          rule.dstRole +
          std::to_string(behaviorState);

      std::string Psi = ns3::ComputeSha256(S);

      std::cout &lt;&lt; "[MICRO-SEG] Ψ: " &lt;&lt; Psi &lt;&lt; "\n";

      if (behaviorState == 0 &amp;&amp;
          rule.effect == ALLOW) {

        if (action == "TRANSFER" || action == "WITHDRAW") {
          m_transferHistory[nodeId].push_back(now);
        }

        return true;
      }

      if (rule.effect == DENY) {
        return false;
      }
    }
  }

  std::cout &lt;&lt; "[MICRO-SEG] Default DENY (Least Privilege)\n";
  return false;
}

// ===================== POLICY INTEGRITY =====================
uint32_t ZtPolicyEngine::GetPolicyVersion() const {
  return m_policyVersion;
}

std::string ZtPolicyEngine::GetPolicyIntegrityHash() const {
  std::stringstream ss;

  ss &lt;&lt; m_policyVersion;

  for (const auto&amp; rule : m_rules) {
    ss &lt;&lt; rule.srcRole
       &lt;&lt; rule.dstRole
       &lt;&lt; rule.action
       &lt;&lt; rule.startHour
       &lt;&lt; rule.endHour
       &lt;&lt; rule.windowSeconds
       &lt;&lt; rule.maxTransfers
       &lt;&lt; rule.effect;
  }

  return ns3::ComputeSha256(ss.str());
}

} // namespace ns3
</code></pre>

zt-tls-handshake.h<pre><code>#ifndef ZT_TLS_HANDSHAKE_H
#define ZT_TLS_HANDSHAKE_H

#include "ns3/object.h"
#include "ns3/node.h"
#include &lt;map&gt;
#include &lt;string&gt;
#include &lt;functional&gt;

namespace ns3 {

/**
 * \ingroup zerotrust
 * \class ZtTlsHandshake
 * \brief Simulates a Zero Trust-based TLS handshake mechanism between NS-3 nodes.
 *
 * This class is responsible for performing identity-validated TLS-like handshakes
 * between IoT nodes, establishing symmetric session keys, and enforcing policy-based
 * authentication using injected policy validation logic.
 */
class ZtTlsHandshake : public Object {
public:
  /**
   * \brief Get the NS-3 TypeId.
   * \return TypeId of the ZtTlsHandshake class.
   */
  static TypeId GetTypeId();

  /**
   * \brief Constructor.
   */
  ZtTlsHandshake();

  /**
   * \brief Start a simulated TLS handshake between client and server nodes.
   *
   * Performs mutual policy validation and generates a symmetric session key
   * shared by both nodes.
   *
   * \param client Pointer to the client node.
   * \param server Pointer to the server node.
   * \param clientId Unique identifier for the client node.
   * \param serverId Unique identifier for the server node.
   */
  void StartHandshake(Ptr&lt;Node&gt; client, Ptr&lt;Node&gt; server, uint32_t clientId, uint32_t serverId);

  /**
   * \brief Check if a session exists for a given peer.
   * \param peerId Node ID of the peer.
   * \return true if a session exists, false otherwise.
   */
  bool HasSession(uint32_t peerId) const;

  /**
   * \brief Retrieve the session key for a peer in hexadecimal string format.
   * \param peerId Node ID of the peer.
   * \return Hex-encoded session key if it exists, empty string otherwise.
   */
  std::string GetSessionKey(uint32_t peerId) const;

  /**
   * \brief Set an external logger for emitting TLS logs.
   * \param logger Function accepting a string message.
   */
  void SetExternalLogger(std::function&lt;void(std::string)&gt; logger);

  /**
   * \brief Set a policy validator for enforcing Zero Trust identity checks.
   * \param validator Function taking node ID and role string, returns true if authorized.
   */
  void SetPolicyValidator(std::function&lt;bool(uint32_t, std::string)&gt; validator);

private:
  /**
   * \brief Emit a log message using the external logger or NS_LOG fallback.
   * \param msg The message to log.
   */
  void Log(const std::string&amp; msg) const;

  std::map&lt;uint32_t, std::string&gt; m_sessionKeys;               //!&lt; Maps node IDs to session keys.
  std::function&lt;void(std::string)&gt; m_logger;                   //!&lt; Optional external logger.
  std::function&lt;bool(uint32_t, std::string)&gt; m_policyValidator; //!&lt; Optional external policy validator.
};

} // namespace ns3

#endif // ZT_TLS_HANDSHAKE_H
